import sys,json,time,urllib.request,urllib.error,copy,subprocess,threading
from pathlib import Path
ROOT=Path('/home/deforest/Documents/DEV/Marathon');sys.path[:0]=[str(ROOT/'scripts/routers'),str(ROOT)]
import codex_local_router as router
OUT=Path(__file__).parent
LIVE=Path('/home/deforest/.config/maya-deepseek/config.json')
MODEL='deepseek-v4.1-flash-1017-iq3-s'
headers=router._external_model_profiles()['deepseek-v4.1-flash-1017-maya'].upstream_headers()
def req(path,data=None,direct=False,timeout=1200):
 h=dict(headers) if not direct else {}
 if data is not None:h['Content-Type']='application/json'
 r=urllib.request.Request(('http://127.0.0.1:19241' if direct else 'http://127.0.0.1:9292')+path,data=None if data is None else json.dumps(data).encode(),headers=h)
 with urllib.request.urlopen(r,timeout=timeout) as f:
  b=f.read();return json.loads(b) if b.lstrip().startswith((b'{',b'[')) else b.decode()
def status():return req('/v1/status',direct=True,timeout=5)
def run(name,changes,restart=True):
 dest=OUT/name;dest.mkdir(exist_ok=True)
 if not (OUT/'original.json').exists():(OUT/'original.json').write_bytes(LIVE.read_bytes())
 cfg=json.loads((OUT/'original.json').read_text())
 if restart:
  try:
   s=status();assert s['activity']['in_flight']==0 and s['activity']['queue']['waiting']==0,'active request - do not restart'
  except urllib.error.URLError:pass
  running=req('/running');print('running',running,flush=True)
  for k,v in changes.get('args',{}).items():
   if k in cfg['args']:cfg['args'][cfg['args'].index(k)+1]=str(v)
   else:cfg['args'] += [k,str(v)]
  cfg['args'] += ['--expert-profile','none']
  cfg['env'].update(changes.get('env',{}));cfg['log']=str(dest/'engine.log')
  (dest/'config.json').write_text(json.dumps(cfg,indent=2)+'\n')
  req('/api/models/unload/'+MODEL,{})
  for _ in range(60):
   state=subprocess.run(['systemctl','--user','show','maya-deepseek-worker.service','-p','ActiveState','--value'],capture_output=True,text=True).stdout.strip()
   if state in ('inactive','failed',''):break
   time.sleep(3)
  else:raise RuntimeError('worker did not stop')
  LIVE.write_text(json.dumps(cfg,indent=2)+'\n')
 prompts=[('warm','Return exactly READY.',32),('decode_a','Write a detailed Python implementation of a stable topological sort, with type annotations, cycle detection, complexity explanation and tests. Begin immediately with the code.',512),('decode_b','Implement an LRU cache in Python using a linked list and a dictionary. Include invariants, edge cases, and tests. Begin immediately with code.',512),('prefill', '\n'.join(f'Record {i:04d}: component node_{i} depends on node_{max(0,i-1)}; weight {(i*37)%991}; state healthy.' for i in range(600))+'\nSummarize how to validate this dependency graph and provide Python code for validation.',384)]
 results=[]
 for label,prompt,n in prompts:
  payload={'model':MODEL,'input':prompt,'reasoning':{'effort':'high'},'temperature':0,'max_output_tokens':n,'store':False}
  t=time.monotonic();wall=time.time()
  try:
   response=req('/v1/responses',payload);elapsed=time.monotonic()-t
   s=status();row={'name':name,'case':label,'seconds':elapsed,'started_at':wall,'usage':response.get('usage'),'status':response.get('status'),'timings':s.get('last_timings'),'context':s.get('context'),'cache_max_tokens':s.get('cache_max_tokens')}
   (dest/(label+'-response.json')).write_text(json.dumps(response,indent=2))
  except Exception as e:
   row={'name':name,'case':label,'seconds':time.monotonic()-t,'error':str(e)}
   if isinstance(e,urllib.error.HTTPError):row['detail']=e.read().decode()[:1500]
  print(json.dumps(row),flush=True);results.append(row);(dest/'results.json').write_text(json.dumps(results,indent=2))
  if 'error' in row:break
 return results
if __name__=='__main__':
 name=sys.argv[1];candidates={'baseline':{},'suffix':{'args':{'--suffix-draft':3}},'tp2':{'args':{'--tp':2,'--suffix-draft':3},'env':{'MAYA_DS4_TP_GGUF_UNEVEN':'1','MAYA_DS4_TP_CHECK':'1','DS4_FLOW_TP':'1'}},'tp4':{'args':{'--tp':4,'--suffix-draft':3},'env':{'MAYA_DS4_TP_GGUF_UNEVEN':'1','MAYA_DS4_TP_CHECK':'1','DS4_FLOW_TP':'1'}},'context262':{'args':{'--max-context':262144,'--suffix-draft':3}}}
 run(name,candidates[name])
